sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    // implement resource here
    try {
        // read query params
        var username = request.queryParams.username;
        var field = (request.queryParams.field || 'opened_by').toString();
        var idType = (request.queryParams.idType || 'user_name').toString();

        // validate
        var allowedFields = ['opened_by', 'caller_id', 'assigned_to'];
        if (!username) {
            response.setStatus(400);
            response.setBody({
                error: 'Missing required query parameter: username'
            });
            return;
        }
        if (allowedFields.indexOf(field) === -1) {
            response.setStatus(400);
            response.setBody({
                error: 'Invalid field. Allowed: ' + allowedFields.join(', ')
            });
            return;
        }

        // find user sys_id (if user passed sys_id directly and idType=sys_id, skip lookup)
        var userSysId = null;
        if (idType === 'sys_id' && GlideStringUtil.nil(username) === false) {
            userSysId = username;
        } else {
            var u = new GlideRecord('sys_user');
            u.addQuery('user_name', username);
            u.query();
            if (!u.next()) {
                response.setStatus(404);
                response.setBody({
                    error: 'User not found with user_name: ' + username
                });
                return;
            }
            userSysId = u.getValue('sys_id');
        }

        // use GlideAggregate to get count efficiently
        var ga = new GlideAggregate('incident');
        ga.addQuery(field, userSysId);
        ga.addAggregate('COUNT');
        ga.query();
        var count = 0;
        if (ga.next()) {
            count = parseInt(ga.getAggregate('COUNT'), 10);
        }

        // response
        response.setStatus(200);
        response.setBody({
            username: username,
            field: field,
            count: count
        });
    } catch (ex) {
        gs.error('Scripted REST error: ' + ex);
        response.setStatus(500);
        response.setBody({
            error: 'Server error',
            detail: ex.toString()
        });
    }
})(request, response);
